bool traceSdMkdir(const char* path,SdTraceSource source){const bool ok=SD.mkdir(path);traceSd(source,SdTraceOperation::Mkdir,ok);return ok;}
bool traceSdExists(const char* path,SdTraceSource source){const bool ok=SD.exists(path);traceSd(source,SdTraceOperation::Exists,ok);return ok;}
