const char eskfPage[]=R"HTML(<!doctype html><meta name=viewport content="width=device-width,initial-scale=1"><style>body{font:16px system-ui;background:#101820;color:#e8eef5;margin:12px}.c{padding:10px;background:#1d2935;border-radius:8px;margin:8px 0;white-space:pre-wrap}button{padding:9px;background:#f7c948;border:0;border-radius:5px}canvas{width:100%;height:120px;background:#081018}</style><h2>ESKF SHADOW</h2><div class=c>Physical outputs: disabled / INA226: NOT INSTALLED / Secondary BNO: NOT INSTALLED</div><div class=c id=s>waiting for control XIAO</div><div class=c id=l>waiting for UART type statistics</div><canvas id=g width=600 height=120></canvas><p><button onclick="fetch('/api/eskf/reset',{method:'POST'})">Reset ESKF only</button></p><script>let a=[];function plot(){let c=g.getContext('2d');c.clearRect(0,0,g.width,g.height);c.strokeStyle='#44d';c.beginPath();a.forEach((v,i)=>{let x=i*g.width/Math.max(1,a.length-1),y=60-v*20;i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke()}async function u(){try{let [j,k]=await Promise.all([fetch('/api/eskf',{cache:'no-store'}).then(r=>r.json()),fetch('/api/link',{cache:'no-store'}).then(r=>r.json())]);l.textContent='UART type statistics\n'+k.types.map(t=>`${t.name}(${t.type}) count ${t.count}; seq ${t.last_sequence}; age ${t.last_age_ms} ms; len ${t.payload_length}/${t.expected_length||'unknown'}; match ${t.length_match}`).join('\n')+`\nTimeSync req/reply/timeout ${k.time_sync.requests}/${k.time_sync.reply_received}/${k.time_sync.timeouts}`;s.textContent=`state ${j.run_state} health ${j.health}\nNED ${j.ned_m.map(x=>x.toFixed(2)).join(' ')} m\nvelocity ${j.velocity_mps.map(x=>x.toFixed(2)).join(' ')} m/s\nobs ${j.observations} reset ${j.reset_count}\nIMU ${j.ages_us.imu} us; sync RTT ${j.time_sync.rtt_us} us\nXIAO link ${j.xiao_link.connected?"CONNECTED":"WAIT"}; age ${j.xiao_link.last_age_ms} ms; type ${j.xiao_link.last_type}\nUART RX ${j.xiao_link.rx_bytes} bytes; frames ${j.xiao_link.frames}; seq gaps ${j.xiao_link.sequence_gaps}\nUART CRC/COBS/LEN ${j.xiao_link.crc_errors}/${j.xiao_link.cobs_errors}/${j.xiao_link.length_errors}`;if(Number.isFinite(j.ned_m[2])){a.push(j.ned_m[2]);if(a.length>120)a.shift();plot()}}catch(e){s.textContent='update failed'}}setInterval(u,50);u()</script>)HTML";
