void setup(){auto cfg=M5.config();cfg.serial_baudrate=115200;M5.begin(cfg);M5.Display.setTextSize(1);M5.Display.setTextColor(0xFFFF,0);bootId=esp_random();if(!bootId)bootId=1;gnssUart.setRxBufferSize(kGnssUartRxBufferBytes);gnssRx.begin(gnssUart);controlUart.setRxBufferSize(16384);controlUart.setTimeout(2);controlUart.begin(kControlUartBaud,SERIAL_8N1,kControlUartRxPin,kControlUartTxPin);SPI.begin(kSdSckPin,kSdMisoPin,kSdMosiPin,kSdCsPin);traceSd(SdTraceSource::Setup,SdTraceOperation::SpiBegin);sdReady=SD.begin(kSdCsPin,SPI,10000000);traceSd(SdTraceSource::Setup,SdTraceOperation::SdBegin,sdReady);if(sdReady)traceSdMkdir(kLogDirectory,SdTraceSource::Setup);sdMutex=xSemaphoreCreateMutex();xTaskCreatePinnedToCore(logTask,"SdWriter",12288,nullptr,1,&logTaskHandle,1);xTaskCreatePinnedToCore(controlRxTask,"UartRx",8192,nullptr,2,&controlRxTaskHandle,1);startWeb();Serial.printf("%s %s SD=%d GNSS RX=%d TX=%d CONTROL RX=%d TX=%d\n",kFirmwareName,kFirmwareVersion,sdReady,kGnssRxPin,kGnssTxPin,kControlUartRxPin,kControlUartTxPin);draw();}
